 "content": "def transform(grid):
    g = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return g
    # The marker adjacent to the colored pattern is its source anchor;
    # the isolated marker marks where the pattern should be reproduced.
    def neighborhood_score(p):
        r, c = p
        return sum(
            1 for rr in range(max(0, r-2), min(len(g), r+3))
            for cc in range(max(0, c-2), min(len(g[0]), c+3))
            if (rr, cc) != p and g[rr][cc] != 0
        )
    source, target = sorted(markers, key=neighborhood_score, reverse=True)
    dr, dc = target[0] - source[0], target[1] - source[1]
    pixels = [(r, c, v) for r, row in enumerate(g) for c, v in enumerate(row)
              if v != 0 and (r, c) != source and v != 5]
    g[target[0]][target[1]] = 0
    for r, c, v in pixels:
        rr, cc = r + dr, c + dc
        if 0 <= rr < len(g) and 0 <= cc < len(g[0]):
            g[rr][cc] = v
    return g
